eventScripts.script:
logger = system.util.getLogger("BallinaPCE.RouteTime")

try:
	if initialChange:
		return

	if not currentValue.quality.isGood():
		logger.warn("Bad quality on trigger tag: {} Quality: {}".format(tagPath, currentValue.quality))
		return

	rawBatchID = currentValue.value

	if rawBatchID is None or str(rawBatchID).strip() == "":
		system.tag.writeBlocking(
			["[DRYPARTS]Line4B/CycleTimes/RouteTime"],
			[None]
		)
		return

	batchID = str(rawBatchID).strip()

	params = {
		"BatchID": batchID
	}

	logger.info("Running QueryDPRoute with BatchID: [{}]".format(batchID))

	result = system.db.runNamedQuery(
		"General_OEE_RevA_0",
		"BatchHistory/QueryDPRoute",
		params
	)

	if result is None or result.getRowCount() == 0:
		routeTime = None
		logger.warn("No result returned for BatchID: [{}]".format(batchID))
	else:
		logger.info("Named Query rows: {}".format(result.getRowCount()))
		logger.info("Named Query columns: {}".format(list(result.getColumnNames())))

		# Explicitly get EA_PER_MIN, not column 0 by assumption
		routeTime = result.getValueAt(0, "EA_PER_MIN")
		routeTime = 60/routeTime

		logger.info("EA_PER_MIN raw result: [{}], type: [{}]".format(routeTime, type(routeTime)))

	writeResults = system.tag.writeBlocking(
		["[DRYPARTS]Line4B/CycleTimes/RouteTime"],
		[routeTime]
	)

	if not writeResults[0].isGood():
		logger.error("Failed to write RouteTime. Quality: {}".format(writeResults[0]))
	else:
		logger.info("RouteTime tag written with value: [{}]".format(routeTime))

except Exception as e:
	logger.error("RouteTime update failed: {}".format(str(e)))

